// Thin wrapper around the CodeSage backend (deployed separately on Railway).
// Set NEXT_PUBLIC_CODESAGE_API_URL in your Vercel project's environment
// variables to your Railway URL, e.g. https://codesage-production.up.railway.app
//
// Updated for the new backend: every endpoint except /health, /auth/signup,
// and /auth/login now requires a Bearer token, ingestion is a background
// job you poll instead of an inline response, and citations come back as
// plain "file:line-line (qualified_name)" strings rather than structured
// objects with a github url.

const BASE_URL =
  process.env.NEXT_PUBLIC_CODESAGE_API_URL ?? "http://localhost:8000";

// ---------------------------------------------------------------------------
// Shared fetch helper
// ---------------------------------------------------------------------------

class ApiError extends Error {
  status: number;
  constructor(message: string, status: number) {
    super(message);
    this.status = status;
  }
}

async function apiFetch(
  path: string,
  token: string | null,
  init: RequestInit = {}
): Promise<Response> {
  const headers = new Headers(init.headers);
  headers.set("Content-Type", "application/json");
  if (token) headers.set("Authorization", `Bearer ${token}`);

  const res = await fetch(`${BASE_URL}${path}`, { ...init, headers });

  if (!res.ok) {
    // The backend returns {"detail": "..."} on HTTPException; surface that
    // message when present instead of a bare status code.
    let detail = `${res.status}`;
    try {
      const body = await res.json();
      if (body?.detail) detail = body.detail;
    } catch {
      // response wasn't JSON (or was empty) — fall back to the status code
    }
    throw new ApiError(detail, res.status);
  }

  return res;
}

// ---------------------------------------------------------------------------
// Auth
// ---------------------------------------------------------------------------

export type AuthResult = {
  accessToken: string;
  userId: string;
  email: string;
};

export async function signup(
  email: string,
  password: string
): Promise<AuthResult> {
  const res = await apiFetch("/auth/signup", null, {
    method: "POST",
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  return { accessToken: data.access_token, userId: data.user_id, email: data.email };
}

export async function login(
  email: string,
  password: string
): Promise<AuthResult> {
  const res = await apiFetch("/auth/login", null, {
    method: "POST",
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  return { accessToken: data.access_token, userId: data.user_id, email: data.email };
}

// ---------------------------------------------------------------------------
// Ingestion — now a background job. POST /ingest returns a job_id right
// away (202 Accepted); poll getIngestStatus until status is "done" or
// "error". pollIngest wraps that loop for you.
// ---------------------------------------------------------------------------

export type JobStatus = "pending" | "running" | "done" | "error";

export type IngestResult = {
  repo: string;
  files_seen: number;
  chunks_indexed: number;
};

export type IngestStatus = {
  jobId: string;
  status: JobStatus;
  source: string;
  repoName: string | null;
  result: IngestResult | null;
  error: string | null;
  createdAt: string;
  startedAt: string | null;
  finishedAt: string | null;
};

function mapIngestStatus(data: any): IngestStatus {
  return {
    jobId: data.job_id,
    status: data.status,
    source: data.source,
    repoName: data.repo_name,
    result: data.result,
    error: data.error,
    createdAt: data.created_at,
    startedAt: data.started_at,
    finishedAt: data.finished_at,
  };
}

export async function startIngest(
  token: string,
  source: string,
  repoName?: string
): Promise<{ jobId: string; status: JobStatus }> {
  const res = await apiFetch("/ingest", token, {
    method: "POST",
    body: JSON.stringify({ source, repo_name: repoName ?? null }),
  });
  const data = await res.json();
  return { jobId: data.job_id, status: data.status };
}

export async function getIngestStatus(
  token: string,
  jobId: string
): Promise<IngestStatus> {
  const res = await apiFetch(`/ingest/status/${jobId}`, token);
  return mapIngestStatus(await res.json());
}

/**
 * Polls GET /ingest/status/{jobId} until the job finishes (done or error).
 * Calls onUpdate after every poll so the caller can show progress. Resolves
 * with the final status; throws if the job itself errored.
 */
export async function pollIngest(
  token: string,
  jobId: string,
  opts: {
    intervalMs?: number;
    timeoutMs?: number;
    onUpdate?: (status: IngestStatus) => void;
  } = {}
): Promise<IngestStatus> {
  const intervalMs = opts.intervalMs ?? 2000;
  const timeoutMs = opts.timeoutMs ?? 5 * 60 * 1000; // ingestion can take minutes
  const startedAt = Date.now();

  while (true) {
    const status = await getIngestStatus(token, jobId);
    opts.onUpdate?.(status);

    if (status.status === "done") return status;
    if (status.status === "error") {
      throw new Error(status.error ?? "Ingestion failed");
    }
    if (Date.now() - startedAt > timeoutMs) {
      throw new Error("Timed out waiting for ingestion to finish");
    }
    await new Promise((r) => setTimeout(r, intervalMs));
  }
}

// ---------------------------------------------------------------------------
// Querying — citations are plain strings like
// "app/main.py:212-233 (ingest)", not structured objects. There's no
// github url from the backend (a repo may have been ingested from a local
// path, not GitHub), so the UI should just render the string.
// ---------------------------------------------------------------------------

export type QueryResult = {
  answer: string;
  citations: string[];
};

export async function queryRepo(
  token: string,
  question: string,
  repoFilter?: string | null
): Promise<QueryResult> {
  const res = await apiFetch("/query", token, {
    method: "POST",
    body: JSON.stringify({ question, repo_filter: repoFilter ?? null }),
  });
  return res.json();
}

// ---------------------------------------------------------------------------
// Repo management
// ---------------------------------------------------------------------------

export type RepoSummary = {
  repo: string;
  chunksIndexed: number;
};

export async function listRepos(token: string): Promise<RepoSummary[]> {
  const res = await apiFetch("/repos", token);
  const data = await res.json();
  return data.repos.map((r: any) => ({
    repo: r.repo,
    chunksIndexed: r.chunks_indexed,
  }));
}

export async function deleteRepo(
  token: string,
  repoName: string
): Promise<{ repo: string; chunksDeleted: number }> {
  const res = await apiFetch(`/repos/${encodeURIComponent(repoName)}`, token, {
    method: "DELETE",
  });
  const data = await res.json();
  return { repo: data.repo, chunksDeleted: data.chunks_deleted };
}

// ---------------------------------------------------------------------------
// Query history
// ---------------------------------------------------------------------------

export type HistoryEntry = {
  id: string;
  question: string;
  answer: string;
  repoFilter: string | null;
  citations: string[];
  createdAt: number;
};

export async function getHistory(
  token: string,
  limit = 50
): Promise<HistoryEntry[]> {
  const res = await apiFetch(`/history?limit=${limit}`, token);
  const data = await res.json();
  return data.history.map((h: any) => ({
    id: h.id,
    question: h.question,
    answer: h.answer,
    repoFilter: h.repo_filter,
    citations: h.citations,
    createdAt: h.created_at,
  }));
}

// ---------------------------------------------------------------------------
// Health
// ---------------------------------------------------------------------------

export async function checkHealth(): Promise<boolean> {
  try {
    const res = await fetch(`${BASE_URL}/health`);
    return res.ok;
  } catch {
    return false;
  }
}

export { ApiError };
